from collections import defaultdict

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    idx = 0
    out = []

    while idx < len(data):
        n = data[idx]
        idx += 1
        if n == 0:
            break

        L = [0] * n
        D = [0] * n

        for man in range(n):
            m = data[idx]
            l = data[idx + 1]
            idx += 2
            L[man] = l

            t = 0
            for _ in range(m):
                s = data[idx]
                e = data[idx + 1]
                idx += 2
                for b in range(s - 6, e - 6):
                    t |= 1 << b
            D[man] = t

        dp_prev = {D[0]: L[0]}
        ans = L[0]

        for i in range(1, n):
            di = D[i]
            li = L[i]
            dp_cur = defaultdict(int)

            for bit, val in dp_prev.items():
                if bit & di == 0:
                    nb = bit | di
                    nv = val + li
                    if nv > dp_cur[nb]:
                        dp_cur[nb] = nv
                if val > dp_cur[bit]:
                    dp_cur[bit] = val

            if li > dp_cur[di]:
                dp_cur[di] = li

            cur_max = max(dp_cur.values())
            if cur_max > ans:
                ans = cur_max

            dp_prev = dp_cur

        out.append(str(ans))

    sys.stdout.write("\n".join(out))

