import sys

def factors(n):
    d = {}
    i = 2
    limit = isqrt(n)
    while i <= limit and n > 1:
        cnt = 0
        while n % i == 0:
            n //= i
            cnt += 1
        if cnt:
            d[i] = cnt
            limit = isqrt(n)
        i += 1
    if n != 1:
        d[n] = d.get(n, 0) + 1
    return d

def inv(x, mod):
    return pow(x, mod - 2, mod)

def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())

    mod = 10**9 + 7
    dic = factors(M)

    max_e = max(dic.values(), default=0)
    SIZE = N + max_e

    fact = [1] * (SIZE + 1)
    for i in range(1, SIZE + 1):
        fact[i] = (fact[i - 1] * i) % mod

    finv = [1] * (SIZE + 1)
    finv[SIZE] = inv(fact[SIZE], mod)
    for i in range(SIZE, 0, -1):
        finv[i - 1] = (finv[i] * i) % mod

    def comb(n, k):
        return fact[n] * finv[k] % mod * finv[n - k] % mod

    ans = 1
    for e in dic.values():
        ans = (ans * comb(e + N - 1, e)) % mod

    print(ans)

