def main():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    edges = [tuple(map(lambda z: int(z) - 1, input().split())) for _ in range(M)]

    if N <= 1:
        print(0)
        return

    adj = [[] for _ in range(N)]
    for a, b in edges:
        adj[a].append(b)
        adj[b].append(a)

    ans = 0

    for skip in range(M):
        a_skip, b_skip = edges[skip]

        parent = list(range(N))
        size = [1] * N

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(a, b):
            ra = find(a)
            rb = find(b)
            if ra == rb:
                return
            if size[ra] < size[rb]:
                ra, rb = rb, ra
            parent[rb] = ra
            size[ra] += size[rb]

        for v in range(N):
            for to in adj[v]:
                if v < to:
                    if (v == a_skip and to == b_skip) or (v == b_skip and to == a_skip):
                        continue
                    union(v, to)

        root0 = find(0)
        connected = True
        for x in range(1, N):
            if find(x) != root0:
                connected = False
                break
        if not connected:
            ans += 1

    print(ans)

