def divisions(n):
    d = collections.defaultdict(int)
    while n % 2 == 0:
        n //= 2
        d[2] += 1

    i = 3
    sq = int(math.isqrt(n))
    while n > 1 and i <= sq:
        if n % i == 0:
            n //= i
            d[i] += 1
            sq = int(math.isqrt(n))
        else:
            i += 2

    if n > 1:
        d[n] += 1

    r = [1]
    for k, v in d.items():
        base = r[:]
        p = 1
        for _ in range(v):
            p *= k
            for c in base:
                r.append(c * p)
    return sorted(r)

