import sys

MOD = 10**9 + 7


class Calc:
    def __init__(self, max_value, mod):
        fact = [1] * (max_value + 1)
        for x in range(2, max_value + 1):
            fact[x] = fact[x - 1] * x % mod

        invs = [1] * (max_value + 1)
        invs[max_value] = pow(fact[max_value], mod - 2, mod)
        for x in range(max_value - 1, 0, -1):
            invs[x] = invs[x + 1] * (x + 1) % mod

        self.fact = fact
        self.invs = invs
        self.mod = mod

    def combination(self, n, r):
        if r < 0 or r > n:
            return 0
        if r == 0:
            return 1
        if r == 1:
            return n
        if n - r < r:
            r = n - r
        return self.fact[n] * self.invs[r] % self.mod * self.invs[n - r] % self.mod


def gen(n):
    x = n
    cnt = 0
    while x % 2 == 0:
        x //= 2
        cnt += 1
    yield cnt

    d = 3
    while d * d <= x:
        cnt = 0
        while x % d == 0:
            x //= d
            cnt += 1
        yield cnt
        d += 2

    if x > 1:
        yield 1


def main():
    data = sys.stdin.buffer.readline().split()
    N = int(data[0])
    M = int(data[1])

    cal = Calc(N + 30, MOD)
    fact = cal.fact
    invs = cal.invs
    mod = cal.mod

    ans = 1
    for cnt in gen(M):
        if cnt:
            n = N + cnt - 1
            if cnt == 1:
                ans = ans * n % mod
            else:
                r = cnt if cnt <= n - cnt else n - cnt
                ans = ans * fact[n] % mod * invs[r] % mod * invs[n - r] % mod

    sys.stdout.write(str(ans))


if __name__ == '__main__':
    main()

