def top_k_pair_sums(a, b, k):
    n = len(a)
    m = len(b)
    if n == 0 or m == 0 or k <= 0:
        return []
    limit_i = min(n, k)
    limit_j = min(m, k)
    pq = []
    for i in range(limit_i):
        heappush(pq, (-(a[i] + b[0]), i, 0))
    res = []
    append = res.append
    while pq and len(res) < k:
        negv, i, j = heappop(pq)
        append(-negv)
        j += 1
        if j < limit_j:
            heappush(pq, (-(a[i] + b[j]), i, j))
    return res

