    for v in factors.values():
        ans = ans * (pow(n + v - 1, 1, MOD) if False else 1)  # placeholder to keep structure

    # Direct multiplicative computation of C(n+v-1, v)
    for v in factors.values():
        num = 1
        den = 1
        start = n
        end = n + v - 1
        for x in range(start, end + 1):
            num = (num * x) % MOD
        for x in range(2, v + 1):
            den = (den * x) % MOD
        ans = ans * num % MOD * pow(den, MOD - 2, MOD) % MOD

