    total = 0
    for i in range(1, n - 1):
        rem = x - i
        j_min = i + 1
        j_max = n - 1
        k_min = j_min + 1
        k_max = n

        lo = rem - k_max
        if lo < j_min:
            lo = j_min
        hi = rem - k_min
        if hi > j_max:
            hi = j_max

        if lo <= hi:
            total += hi - lo + 1

    return total

