def solve(N: int, M: int, a: "List[int]", b: "List[int]"):
    adj = [[] for _ in range(N)]
    for u, v in zip(a, b):
        u -= 1
        v -= 1
        adj[u].append(v)
        adj[v].append(u)

    answer = 0

