def prime_factorize_by_osa_k(max_val):
    self = type("prime_factorize_by_osa_k", (), {})()
    minFactor = [-1] * (max_val + 1)
    for i in range(2, max_val + 1):
        if minFactor[i] == -1:
            minFactor[i] = i
            start = i * i
            if start > max_val:
                continue
            for j in range(start, max_val + 1, i):
                if minFactor[j] == -1:
                    minFactor[j] = i
    self.minFactor = minFactor

    def osa_k(n):
        d = {}
        now = n
        while now > 1:
            p = minFactor[now]
            d[p] = d.get(p, 0) + 1
            now //= p
        return d

    self.osa_k = osa_k
    return self

