import sys

class UnionFind:
    def __init__(self, n):
        self.n = n
        self.parents = [-1] * n

    def find(self, x):
        parents = self.parents
        while parents[x] >= 0:
            if parents[parents[x]] >= 0:
                parents[x] = parents[parents[x]]
            x = parents[x]
        return x

    def union(self, x, y):
        parents = self.parents
        x = self.find(x)
        y = self.find(y)
        if x == y:
            return
        if parents[x] > parents[y]:
            x, y = y, x
        parents[x] += parents[y]
        parents[y] = x

    def same(self, x, y):
        return self.find(x) == self.find(y)


