    for i in range(M):
        uf = UnionFind(N)
        for j, (a, b) in enumerate(edge):
            if j != i:
                uf.union(a, b)
        if sum(1 for p in uf.parents if p < 0) >= 2:
            ans += 1

    print(ans)


