    adj = [[] for _ in range(n)]
    edges = []

    for _ in range(m):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        adj[u].append(v)
        adj[v].append(u)
        edges.append((u, v))

    if m == 0:
        print(0)
        return

    # Find bridges using iterative Tarjan algorithm
    tin = [-1] * n
    low = [0] * n
    parent = [-1] * n
    parent_edge_idx = [-1] * n
    timer = 0
    bridges = set()

    for start in range(n):
        if tin[start] != -1:
            continue

        stack = [(start, 0, 0)]  # (node, next_neighbor_index, state 0=enter/iterate)
        parent[start] = -1
        while stack:
            v, idx, state = stack.pop()
            if state == 0:
                if tin[v] == -1:
                    tin[v] = low[v] = timer
                    timer += 1

                if idx < len(adj[v]):
                    to = adj[v][idx]
                    stack.append((v, idx + 1, 0))
                    if to == parent[v]:
                        continue
                    if tin[to] == -1:
                        parent[to] = v
                        stack.append((to, 0, 0))
                    else:
                        low[v] = min(low[v], tin[to])
                else:
                    p = parent[v]
                    if p != -1:
                        low[p] = min(low[p], low[v])
                        if low[v] > tin[p]:
                            bridges.add((p, v) if p < v else (v, p))

    ans = 0
    for u, v in edges:
        if (u, v) in bridges or (v, u) in bridges:
            ans += 1

    print(ans)

