def solve(amount):
    best_price = (amount + 199) // 200 * 380

    max_c1 = amount // 1500
    max_b1 = amount // 1200
    max_a1 = amount // 1000
    max_c = amount // 500
    max_b = amount // 300

    for c1 in range(max_c1 + 1):
        rem1 = amount - c1 * 1500
        price1 = c1 * 2244

        for b1 in range(min(max_b1, rem1 // 1200) + 1):
            rem2 = rem1 - b1 * 1200
            price2 = price1 + b1 * 1870

            for a1 in range(min(max_a1, rem2 // 1000) + 1):
                rem3 = rem2 - a1 * 1000
                price3 = price2 + a1 * 1520

                for c in range(min(max_c, rem3 // 500) + 1):
                    rem4 = rem3 - c * 500
                    price4 = price3 + c * 850

                    bmax = min(max_b, rem4 // 300)
                    for b in range(bmax + 1):
                        rem5 = rem4 - b * 300
                        if rem5 % 200 == 0:
                            price = price4 + b * 550 + (rem5 // 200) * 380
                            if price < best_price:
                                best_price = price

    return best_price


