def solve_case(AB, T):
    dp = [0] * T
    ans = 0
    for a, b in AB:
        ndp = dp[:]
        if a >= T:
            m = max(dp)
            v = m + b
            if v > ans:
                ans = v
        else:
            limit = T - a
            for t in range(limit):
                v = dp[t] + b
                if v > ndp[t + a]:
                    ndp[t + a] = v
            for t in range(limit, T):
                v = dp[t] + b
                if v > ans:
                    ans = v
        dp = ndp
    m = max(dp)
    if m > ans:
        ans = m
    return ans

