from math import gcd

def gen_d_prim(n):
    D = [n + 1 if i % 2 else 2 for i in range(n + 1)]
    if n >= 0:
        D[0] = 0
    if n >= 1:
        D[1] = 0
    for i in range(3, n + 1, 2):
        if D[i] != n + 1:
            continue
        for j in range(i, n + 1, i):
            D[j] = i
    return D

def is_pairwise(A):
    if not A:
        return True
    max_a = max(A)
    D = gen_d_prim(max_a)
    past = set()
    for a in A:
        now = set()
        while a != 1:
            p = D[a]
            if p not in now and p in past:
                return False
            now.add(p)
            past.add(p)
            a //= p
    return True

def gcd_all(A):
    g = 0
    for a in A:
        g = gcd(g, a)
    return g

def solve():
    if is_pairwise(A):
        return 0
    if gcd_all(A) == 1:
        return 1
    return 2

