def fft(A, B):
    import numpy as np
    from numpy.fft import rfft, irfft

    MAXA = max(A)
    MAXB = max(B)

    C1 = np.bincount(A, minlength=MAXA + 1)
    C2 = np.bincount(B, minlength=MAXB + 1)

    L = 1 << (MAXA + MAXB).bit_length()

    res = irfft(rfft(C1, L) * rfft(C2, L), L)
    return np.rint(res).astype(np.int64)

